options(mc.cores=1L);source('cellchat_nichechat_fibro7/scripts/nichenet_common.R');setDTthreads(1);library(edgeR);library(limma)
O<-'results/C5_Endothelial_NicheNet_spatial_v1';b<-readRDS(file.path(O,'01_receiver_pseudobulk/Endothelial_patient_pseudobulk.rds'));p<-as.data.table(b$metadata);sel<-which(p$eligible & p$stage%in%c('NMIBC','MIBC'));d<-copy(p[sel]);d[,`:=`(z=as.numeric(scale(fraction)),dataset=factor(dataset),stage=factor(stage))];design<-model.matrix(~dataset+stage+z,d);status<-data.table(n_patients=nrow(d),columns=ncol(design),rank=qr(design)$rank,residual_df=nrow(d)-ncol(design));fwrite(status,file.path(O,'01_receiver_pseudobulk/stage_model_audit.tsv'),sep='\t')
if(qr(design)$rank==ncol(design)&&nrow(d)-ncol(design)>=5){y<-DGEList(as.matrix(b$counts[,sel,drop=FALSE]));y<-y[filterByExpr(y,design=design),,keep.lib.sizes=FALSE];y<-calcNormFactors(y);f<-eBayes(lmFit(voom(y,design,plot=FALSE),design),robust=TRUE);tt<-as.data.table(topTable(f,coef='z',n=Inf,sort.by='none'),keep.rownames='gene');j<-match('z',colnames(design));tt[,SE:=f$stdev.unscaled[,j]*sqrt(f$s2.post)];fwrite(tt,file.path(O,'01_receiver_pseudobulk/DE_stage_adjusted.tsv'),sep='\t');fwrite(d,file.path(O,'01_receiver_pseudobulk/design_stage_adjusted.tsv'),sep='\t')}else writeLines('NOT_EVALUABLE: stage design rank/residual df',file.path(O,'01_receiver_pseudobulk/stage_status.txt'))
